}", "new_text": "// 跟随宿主：压缩那一跳沿用「当前会话」的模型（避免副模型与会话模型不一致）
//
// 模型来源优先级：
//   1. n.model —— 当前会话归一化请求里的模型（宿主 0.9+ 的唯一来源，每次请求都带）
//   2. options.model —— 旧宿主（0.8）仍会在请求选项里传的模型
//   3. cfg.model —— 兜底
//
// 注意：这里的状态必须是「每个插件实例一份」，且每次 observe 都用当前请求覆盖，
// 不能是模块级变量，否则会把上一次会话的模型泄漏到下一次会话。
export function makeHostFollow(cfg) {
  let currentModel = null
  return {
    observe(options, n) {
      const model = (n && n.model) || (options && options.model)
      if (model) currentModel = model
    },
    callConfig(options, n) {
      const model = (n && n.model) || (options && options.model) || currentModel || cfg.model
      return { ...cfg, model }
    },
  }
}"}
